}

contracts/LPCallback.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraPool.sol';
import "./interfaces/ILPPluginFactory.sol";
import '@cryptoalgebra/integral-periphery/contracts/interfaces/external/IWNativeToken.sol';
import '@cryptoalgebra/integral-periphery/contracts/libraries/TransferHelper.sol';
import '@cryptoalgebra/integral-periphery/contracts/libraries/LiquidityAmounts.sol';
import '@cryptoalgebra/integral-core/contracts/libraries/TickMath.sol';
import "./interfaces/ILPCallback.sol";

contract LPCallback is ILPCallback {

    address public immutable pool;
    address internal immutable pluginFactory;
    address public immutable plugin;
    PoolAddress.PoolKey internal poolKey;

    event PositionMinted(uint256 amount0, uint256 amount1, uint128 liquidity);

    constructor(address _pool, address _pluginFactory, address _plugin) {
        pool = _pool;
        pluginFactory = _pluginFactory;
        plugin = _plugin;
        poolKey = PoolAddress.PoolKey({
            deployer: address(0),
            token0: address(0),
            token1: address(0)
        });
    }

    function algebraMintCallback(
        uint256 amount0Owed,
        uint256 amount1Owed,
        bytes calldata data
    ) external override {
        CallbackStructs.MintCallbackData memory decoded = abi.decode(data, (CallbackStructs.MintCallbackData));
        require(msg.sender == pool, "Invalid caller of callback");
        IAlgebraPool algebraPool = IAlgebraPool(pool);

        if (amount0Owed > 0)
            _pay(algebraPool.token0(), decoded.payer, msg.sender, amount0Owed);
        if (amount1Owed > 0)
            _pay(algebraPool.token1(), decoded.payer, msg.sender, amount1Owed);
    }

    function mint(
        address leftoversRecipient,
        int24 tickLower,
        int24 tickUpper,
        uint256 amount0,
        uint256 amount1
    ) external override returns(uint256 amount0Returned, uint256 amount1Returned, uint128 returnedLiquidity) {

        (uint160 price, , , , , ) = IAlgebraPool(pool).globalState();
        uint128 liquidity = LiquidityAmounts.getLiquidityForAmounts(
            price,
            TickMath.getSqrtRatioAtTick(tickLower),
            TickMath.getSqrtRatioAtTick(tickUpper),
            amount0,
            amount1
        );

        (amount0Returned, amount1Returned, returnedLiquidity) = IAlgebraPool(pool).mint(
            leftoversRecipient,
            plugin,
            tickLower,
            tickUpper,
            liquidity,
            abi.encode(CallbackStructs.MintCallbackData({poolKey: poolKey, payer: msg.sender}))
        );

        emit PositionMinted(amount0Returned, amount1Returned, returnedLiquidity);
    }

    function _pay(
        address token,
        address payer,
        address recipient,
        uint256 value
    ) private {
        address WNativeToken = ILPPluginFactory(pluginFactory).WNativeToken();
        if (token == WNativeToken && address(this).balance >= value) {
            // pay with WNativeToken
            // "address(this).balance >= value" may unexpectedly become false (including due to frontrun)
            // so this function should be accompanied by a `refundNativeToken` in multicall to avoid potential loss of tokens
            IWNativeToken(WNativeToken).deposit{value: value}(); // wrap only what is needed to pay
            IWNativeToken(WNativeToken).transfer(recipient, value);
        } else if (payer == address(this)) {
            // pay with tokens already in the contract (for the exact input multihop case)
            TransferHelper.safeTransfer(token, recipient, value);
        } else {
            // pull payment
            TransferHelper.safeTransferFrom(token, payer, recipient, value);
        }
    }
}

contracts/LPToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Import ERC20 standard implementation from OpenZeppelin
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
// Import Ownable from OpenZeppelin to manage ownership-based access control
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LPToken
 * @notice ERC20 token representing a share of liquidity provided in a pool.
 *         Only the owner (e.g., the LPPlugin contract) can mint or burn tokens.
 */
contract LPToken is ERC20, Ownable {
    /**
     * @notice Constructor initializes the ERC20 token with a name and symbol
     *         and sets the deployer as the initial owner.
     * @param name Token name
     * @param symbol Token symbol
     */
    constructor(
        string memory name,
        string memory symbol
    ) ERC20(name, symbol) Ownable(msg.sender) {}

    /**
     * @notice Mint new LP tokens to a user
     * @dev Only callable by the contract owner (typically the LPPlugin)
     * @param to Address receiving the minted tokens
     * @param amount Number of tokens to mint
     */
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    /**
     * @notice Burn LP tokens from a user
     * @dev Only callable by the contract owner (typically the LPPlugin)
     * @param from Address whose tokens will be burned
     * @param amount Number of tokens to burn
     */
    function burn(address from, uint256 amount) external onlyOwner {
        _burn(from, amount);
    }
}

contracts/LPTokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {ILPTokenFactory} from "./interfaces/ILPTokenFactory.sol";
import {LPToken} from "./LPToken.sol";
import "hardhat/console.sol";

contract LPTokenFactory is ILPTokenFactory {
    constructor() {}

    function create(string memory symbol, string memory name) external returns(address) {
        LPToken token = new LPToken(symbol, name);
        token.transferOwnership(msg.sender);
        return address(token);
    }
}

